package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import org.json.*;import java.io.*;import com.insight.quantlife.*;
/** Dedicated synthetic, offline AVD only. Never run against a personal device. */
public class WikiInsightsTest extends LearningIntegrityTest {
 final String aid="insight-synthetic-a",bid="insight-synthetic-b",at="洞见合成甲",bt="洞见合成乙";
 void snap(String name)throws Exception{h.tap("#editor .dialog-top h2",false);runOnMainSync(()->h.web.invalidate());Thread.sleep(1500);check(h.activity.hasWindowFocus()&&h.web.isShown(),"Visible Android window at "+name);h.screenshot(name);}
 JSONObject data()throws Exception{return (JSONObject)h.call("getWikiInsights",new JSONObject());}
 void rejected(String action,JSONObject p,String label)throws Exception{boolean bad=false;try{h.call(action,p);}catch(Exception x){bad=true;}check(bad,label);}
 void seedInsights()throws Exception{check(getTargetContext().getPackageManager().getPackageInfo(getTargetContext().getPackageName(),0).versionName.equals("1.7.10"),"Seed signed 1.7.10");try(FileOutputStream o=getTargetContext().openFileOutput("insights-baseline.json",0)){o.write(snapshotData().toString().getBytes("UTF-8"));}}
 void upgradeCheck()throws Exception{
  JSONObject before;try(InputStream in=getTargetContext().openFileInput("insights-baseline.json");ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);before=new JSONObject(out.toString("UTF-8"));}
  check(getTargetContext().getPackageManager().getPackageInfo(getTargetContext().getPackageName(),0).versionName.equals("1.8.0"),"Same-signature cover upgrade to 1.8.0");JSONObject after=snapshotData();
  for(String k:new String[]{"records","messages","wikiPages","chatSession","settings","raw","gpx"})check(before.get(k).toString().equals(after.get(k).toString()),"Upgrade preserves "+k);
  check(data().getJSONArray("reports").length()==0,"New derived tables start empty without touching originals");
 }
 void compilePages()throws Exception{
  h.js("window.__insData="+init()+";window.__insPages=['"+at+"','"+bt+"'].map(topic=>{const rs=LifeWiki.topicRecords(__insData.records,topic);return LifeWiki.indexPage(LifeWiki.validatePage({summary:topic+'的合成主题摘要',aliases:[],concepts:[],sourceIds:rs.map(r=>r.id)},rs,topic),__insData.records)});");
  JSONArray ps=new JSONArray(h.js("__insPages"));for(int i=0;i<ps.length();i++)h.call("saveWiki",new JSONObject().put("page",ps.getJSONObject(i)));
 }
 void reviewMock()throws Exception{
  chatMock();h.js("window.__reviewCalls=[];window.__reviewBase=LifeNative.call.bind(LifeNative);LifeNative.call=function(action,payload,rid){const p=JSON.parse(payload);if(action!=='ask'||p.tool.name!=='review_life_knowledge'){__reviewBase(action,payload,rid);return;}__reviewCalls.push(p);const d=JSON.parse(p.messages.at(-1).content),sides=d.pages.map(page=>{const r=d.sources.find(r=>page.sourceIds.includes(r.id));return {pageId:page.id,claim:page.topic+'观点需核对条件',evidence:[{recordId:r.id,quote:r.excerpts[0].text}]}});const f=k=>({kind:k,title:k==='gap'?'合成：缺少实践验证':k==='conflict'?'合成：先设计还是先试运行':'合成：输入质量的共同机制',reason:'仅为待核对线索，可能是不同业务阶段；不能直接推出普遍规律。',question:'适用阶段和验证结果是否已记录？',nextStep:'可补充一个独立实践，记录边界条件及结果。',sides:k==='gap'?sides.slice(0,1):sides});setTimeout(()=>nativeReply({id:rid,data:{text:JSON.stringify({findings:d.pages.length===2?[f('connection'),f('conflict')]:[f('gap')]}),model:'synthetic-offline'}}),10);}");
 }
 void autoRun()throws Exception{
  reload();holdAutomation();reviewMock();h.js("Object.defineProperty(document,'hidden',{configurable:true,get:()=>false});AutoWiki.resume()");
  until("__reviewCalls.length>=2");for(int i=0;i<200;i++){JSONArray reports=data().getJSONArray("reports");boolean pair=false;for(int j=0;j<reports.length();j++){JSONObject r=reports.getJSONObject(j);if(r.getJSONArray("pageIds").length()==2&&r.getJSONArray("findings").length()==2&&r.getJSONObject("sourceVersions").getLong(aid)==find(aid).getLong("updatedAt"))pair=true;}if(pair)break;Thread.sleep(100);}
  holdAutomation();check(data().getJSONArray("reports").length()>=3,"Actual idle automation persists single-topic and cross-topic discoveries");jsCheck("__reviewCalls.every(p=>p.automaticWiki&&p.tool.name==='review_life_knowledge')","Actual automatic model requests use read-only evidence review tool");
 }
 JSONObject pair()throws Exception{JSONArray rows=data().getJSONArray("reports");for(int i=0;i<rows.length();i++)if(rows.getJSONObject(i).getJSONArray("pageIds").length()==2)return rows.getJSONObject(i);throw new Exception("No pair");}
 JSONObject reviewPayload(JSONObject report,String state,String note,long version)throws Exception{return new JSONObject().put("reportId",report.getString("id")).put("findingId",report.getJSONArray("findings").getJSONObject(0).getString("id")).put("signature",report.getString("signature")).put("state",state).put("note",note).put("expectedVersion",version);}
 void open(String kind)throws Exception{h.js("WikiInsightsUI.open("+JSONObject.quote(kind)+")");until("document.querySelector('#insight-list')!==null");}
 void flow()throws Exception{
  if(find("insight-synthetic-new")!=null)h.call("deleteRecord",new JSONObject().put("id","insight-synthetic-new"));
  h.call("saveSettings",new JSONObject().put("settings",new JSONObject().put("profile",model("SYNTHETIC-ONLY"))));
  JSONObject a=note(aid,"企业决策之前需要验证数据质量和业务指标定义。").put("type","learning").put("title",at).put("tags",new JSONArray().put(at)).put("platform","合成平台").put("contentType","article").put("durationMinutes",30);
  JSONObject b=note(bid,"这个项目先上线收集数据，再逐步验证数据质量和指标定义。").put("title",bt).put("tags",new JSONArray().put(bt));
  h.call("saveRecord",new JSONObject().put("record",a).put("allowDuplicate",true));h.call("saveRecord",new JSONObject().put("record",b).put("allowDuplicate",true));compilePages();
  // Clear only disposable AVD's old derived topic caches to isolate automatic scheduling, not original records.
  JSONArray pages=init().getJSONArray("wikiPages");for(int i=0;i<pages.length();i++){JSONObject p=pages.getJSONObject(i);if(!p.getString("topic").equals(at)&&!p.getString("topic").equals(bt))h.call("deleteWiki",new JSONObject().put("id",p.getString("id")));}
  while(queue().getInt("count")>0)h.call("ackWikiQueue",new JSONObject().put("jobs",queue().getJSONArray("jobs")));
  autoRun();JSONObject report=pair();check(report.getJSONArray("findings").length()==2,"Different domains retain a connection and both conflict sides");check(find(aid).getString("note").equals(a.getString("note"))&&find(bid).getString("note").equals(b.getString("note")),"Discovery never rewrites original learning/work notes");
  JSONObject fake=new JSONObject(report.toString());fake.getJSONArray("findings").getJSONObject(0).getJSONArray("sides").getJSONObject(0).getJSONArray("evidence").getJSONObject(0).put("quote","这是一段不存在于原始笔记中的伪造引文");rejected("saveWikiInsight",new JSONObject().put("report",fake),"Native SQLite independently rejects fabricated quote");
  click("[data-page=chat]");open("connection");jsCheck("document.querySelectorAll('[data-insight]').length===1&&document.querySelectorAll('[data-insight-kind]').length===3","Actual green Wiki panel has three discovery tabs");snap("wiki-insights-list-1.8.0.png");
  click("[data-insight]");jsCheck("document.querySelectorAll('.insight-side blockquote').length===2&&document.querySelectorAll('[data-insight-source]').length===2","Connection detail displays original quotes and tappable sources");snap("wiki-insights-detail-1.8.0.png");
  click("[data-insight-source]");jsCheck("document.querySelector('#editor').innerText.includes('企业决策之前')||document.querySelector('#editor').innerText.includes('先上线收集数据')","Source button opens the actual original record");
  open("connection");click("[data-insight]");click("[data-insight-review=resolved]");jsCheck("document.querySelector('#toast').innerText.includes('核对结论')","Resolved requires a personal verification explanation");
  h.js("document.querySelector('#insight-review-note').value='只适用于验证成本较低的试运行阶段。'");click("[data-insight-review=followup]");until("document.querySelector('#insight-detail>p.hint').innerText.startsWith('待跟进')");
  JSONObject reviewed=(JSONObject)h.call("reviewWikiInsight",reviewPayload(report,"resolved","合成验证：两种做法针对不同业务阶段。",data().getJSONArray("reviews").getJSONObject(0).getLong("updatedAt")));check(reviewed.getString("state").equals("resolved"),"Native review persists user conclusion separately from findings");
  rejected("reviewWikiInsight",reviewPayload(report,"followup","旧客户端说明",0),"Concurrent review version rejects stale overwrite");rejected("reviewWikiInsight",reviewPayload(report,"resolved","",reviewed.getLong("updatedAt")),"Native resolved also rejects missing explanation");
  reload();holdAutomation();open("connection");click("[data-insight]");jsCheck("document.querySelector('#insight-review-note').value.includes('不同业务阶段')","Review and conclusion persist across reload");
  h.js("document.querySelector('#insight-review-note').value='该联系不适用于目前项目'");click("[data-insight-review=dismissed]");until("document.querySelector('#insight-detail>p.hint').innerText.startsWith('暂不采纳')");click("#insight-back");jsCheck("document.querySelectorAll('[data-insight]').length===0","Dismissed discovery leaves default list");click("#insight-hidden");jsCheck("document.querySelectorAll('[data-insight]').length>=1","Dismissed discovery remains in inspectable history");
  for(String k:new String[]{"conflict","gap"}){click("[data-insight-kind="+k+"]");jsCheck("document.querySelectorAll('[data-insight]').length>0","Actual "+k+" tab contains evidence-backed result");}snap("wiki-insights-gaps-1.8.0.png");
  click("#close-editor");reload();holdAutomation();chatMock();click("[data-page=chat]");sendText("我有哪些观点冲突？");jsCheck("__calls.some(p=>p.tool.name==='prepare_life_records'&&p.messages[0].content.includes('knowledgeInsights')&&p.messages[0].content.includes('conflict')&&!p.messages[0].content.includes('dailySeries'))","Actual chat receives relevant discovery evidence without unrelated time series");
  JSONObject changed=find(aid);changed.put("note",changed.getString("note")+" 新增合成实践：对照一周输入质量和返工记录，仍需核实因果。");h.call("saveRecord",new JSONObject().put("record",changed).put("allowDuplicate",true));reload();holdAutomation();
  h.js("window.__current="+init()+";window.__insights="+data()+";");jsCheck("WikiInsights.context(__insights,__current.wikiPages,__current.records,'观点冲突',{}).findings.length===0","Source edit immediately excludes stale conflict from chat");rejected("saveWikiInsight",new JSONObject().put("report",report),"Old source version cannot overwrite a new note");rejected("reviewWikiInsight",reviewPayload(report,"pending","",0),"Stale source cannot be marked verified");
  open("connection");click("#insight-hidden");click("[data-insight]");jsCheck("!document.querySelector('[data-insight-review]')&&document.querySelector('#insight-detail').innerText.includes('待复核')","Stale result is viewable but cannot be reviewed");
  compilePages();while(queue().getInt("count")>0)h.call("ackWikiQueue",new JSONObject().put("jobs",queue().getJSONArray("jobs")));autoRun();
  check(data().getJSONArray("history").length()>=2,"Reanalysis archives prior findings rather than losing previous conflict");check(data().getJSONArray("reviews").length()>0,"Previous personal review remains retained");
  open("connection");click("[data-insight]");jsCheck("document.querySelector('#insight-detail').innerText.includes('待核对')&&!document.querySelector('#insight-review-note').value","Changed evidence does not inherit old dismissal or resolution");click("#insight-back");click("#insight-hidden");jsCheck("document.querySelectorAll('[data-insight]').length>=2","Previous and current evidence versions can both be inspected");
  jsCheck("document.documentElement.scrollWidth<=innerWidth+1&&getComputedStyle(document.documentElement).getPropertyValue('--green').trim()==='#216a54'&&document.querySelectorAll('.bottom-nav button').length===4","No horizontal overflow, original green theme and four navigation tabs preserved");snap("wiki-insights-history-1.8.0.png");
  JSONObject current=pair();h.call("saveRecord",new JSONObject().put("record",note("insight-synthetic-new","新增同主题来源，原页面不能代表完整来源集合。").put("title",at).put("tags",new JSONArray().put(at))).put("allowDuplicate",true));
  rejected("saveWikiInsight",new JSONObject().put("report",current),"Concurrent new matching source invalidates native discovery scope");
  h.call("deleteRecord",new JSONObject().put("id",bid));rejected("saveWikiInsight",new JSONObject().put("report",current),"Deleted source rejects persisted discovery");
 }
 @Override public void onStart(){Bundle out=new Bundle();try{h=new MainHost(this);h.open();holdAutomation();if(phase.equals("seed"))seedInsights();else{if(phase.equals("upgrade"))upgradeCheck();flow();}out.putString("stream","PASS "+passed+" knowledge-discovery/native/UI/upgrade checks; offline synthetic model only\n");finish(Activity.RESULT_OK,out);}catch(Throwable e){try{h.screenshot("wiki-insights-failure.png");}catch(Exception ignored){}out.putString("stream","FAIL after "+passed+": "+e+"\n");finish(Activity.RESULT_CANCELED,out);}}
}
